<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/customer_superapp_v1200.php';$u=sk1200_user();$uid=(int)($u['id']??0);if($uid<1){header('Location: /login.php?next='.rawurlencode('/business-opportunities-v1200.php'));exit;}$msg='';$err='';try{if(($_SERVER['REQUEST_METHOD']??'')==='POST'){csrf_check();sk1200_submit_offer((int)($_POST['match_id']??0),$uid,$_POST);$msg='Offer sent to customer.';}}catch(Throwable $e){$err=$e->getMessage();}$rows=sk1200_opportunities($uid);?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Customer Opportunities</title><link rel="stylesheet" href="/assets/customer-superapp-v1200.css?v=1200"></head><body><main class="cs1200 provider"><header class="top"><a class="brand" href="/">← ShahkotPK</a><div><span>BUSINESS OPPORTUNITIES</span><h1>Customers who need what you offer</h1><p>Reply with a factual price/message. Do not spam customers or claim unavailable services.</p><p><a href="/business-orders-v1230.php">Open Commerce Orders →</a></p></div></header><?php if($msg):?><div class="notice ok"><?=sk1200_h($msg)?></div><?php endif;?><?php if($err):?><div class="notice bad"><?=sk1200_h($err)?></div><?php endif;?><section class="panel"><div class="head"><div><span>LEADS</span><h2><?=count($rows)?> matched requests</h2></div></div><div class="opportunities"><?php foreach($rows as $r):?><article><header><b><?=sk1200_h($r['business_name'])?></b><span><?=sk1200_h($r['urgency'])?></span></header><p><?=nl2br(sk1200_h($r['need_text']))?></p><small>📍 <?=sk1200_h($r['area']?:'Area not specified')?> <?php if((float)$r['budget_max']>0):?> · Budget up to PKR <?=number_format((float)$r['budget_max'],0)?><?php endif;?></small><?php if($r['status']==='offered'):?><div class="sent"><b>Offer sent: <?=$r['offer_price']>0?'PKR '.number_format((float)$r['offer_price'],0):'Message only'?></b><p><?=sk1200_h($r['offer_message'])?></p></div><?php else:?><form method="post"><input type="hidden" name="_csrf" value="<?=sk1200_h(csrf_token())?>"><input type="hidden" name="match_id" value="<?=(int)$r['id']?>"><label>Price (optional)<input type="number" min="0" step="1" name="offer_price"></label><label>Offer / availability<textarea name="offer_message" rows="3" maxlength="1500" placeholder="Example: Available today after 5 PM. Service visit PKR 2,500 excluding parts."></textarea></label><button>Send Offer</button></form><?php endif;?></article><?php endforeach;?><?php if(!$rows):?><p class="empty">No matched customer requests right now.</p><?php endif;?></div></section></main></body></html>